+ export 'FA_PROVIDERS_QUEUE=[{"provider_type":"zai","provider_config":{"model":"glm-test","apiKeyEnv":"ZAI_CODE_KEY"}},{"provider_type":"zai","provider_config":{"model":"glm-test","apiKeyEnv":"ZAI_CODE_KEY_1"}}]'
+ FA_PROVIDERS_QUEUE='[{"provider_type":"zai","provider_config":{"model":"glm-test","apiKeyEnv":"ZAI_CODE_KEY"}},{"provider_type":"zai","provider_config":{"model":"glm-test","apiKeyEnv":"ZAI_CODE_KEY_1"}}]'
+ _fa_append_fallback_keys
+ command -v node
+ '[' -n '[{"provider_type":"zai","provider_config":{"model":"glm-test","apiKeyEnv":"ZAI_CODE_KEY"}},{"provider_type":"zai","provider_config":{"model":"glm-test","apiKeyEnv":"ZAI_CODE_KEY_1"}}]' ']'
+ local enriched
++ FA_PROVIDERS_QUEUE='[{"provider_type":"zai","provider_config":{"model":"glm-test","apiKeyEnv":"ZAI_CODE_KEY"}},{"provider_type":"zai","provider_config":{"model":"glm-test","apiKeyEnv":"ZAI_CODE_KEY_1"}}]'
++ FA_DEFAULT_URLS_JSON='{"zai":"https://api.z.ai/api/coding/paas/v4","copilot":"https://api.enterprise.githubcopilot.com","anthropic":"https://api.anthropic.com","openai":"https://api.openai.com/v1","openrouter":"https://openrouter.ai/api/v1","google":"https://generativelanguage.googleapis.com/v1beta"}'
++ node -e $'
    const fs = require("fs");
    let raw = process.env.FA_PROVIDERS_QUEUE || "";
    if (raw.startsWith("@")) raw = fs.readFileSync(raw.slice(1), "utf8");
    let arr;
    try { arr = JSON.parse(raw); } catch (e) { process.exit(0); }
    if (!Array.isArray(arr) || arr.length === 0) process.exit(0);
    const defaults = JSON.parse(process.env.FA_DEFAULT_URLS_JSON);
    const refOf = (e) => (e && e.provider_config && (e.provider_config.apiKeyEnv || e.provider_config.apiKeyEnvVar)) || null;
    const seen = new Set(arr.map(refOf).filter(Boolean));
    const out = [];
    const appended = [];
    for (const entry of arr) {
      out.push(entry);
      const k = refOf(entry);
      if (!k || !entry.provider_type || !entry.provider_config) continue;
      for (let i = 1; i <= 5; i++) {
        const fb = k + "_" + i;
        if (seen.has(fb)) break;
        if (!process.env[fb] && !process.env[fb + "_BASE64"]) continue;
        const clone = JSON.parse(JSON.stringify(entry.provider_config));
        if (clone.apiKeyEnv !== undefined) clone.apiKeyEnv = fb;
        else if (clone.apiKeyEnvVar !== undefined) clone.apiKeyEnvVar = fb;
        else clone.apiKeyEnv = fb;
        if (!clone.baseUrl) {
          const d = defaults[entry.provider_type];
          if (!d) continue;
          clone.baseUrl = d;
        }
        const ne = { provider_type: entry.provider_type, provider_config: clone };
        if (entry.name) ne.name = entry.name + "-" + i;
        out.push(ne);
        seen.add(fb);
        appended.push(fb);
      }
    }
    if (appended.length === 0) process.exit(0);
    process.stderr.write("[providers/fa.sh] fallback provider keys appended to the queue: " + appended.join(", ") + "\n");
    process.stdout.write(JSON.stringify(out));
  '
+ enriched=
+ '[' -n '' ']'
+ return 0
